classes.className:
`w-[15.063rem] rounded-[16px] bg-color-white border-color-white border-solid border-[1px] box-border overflow-hidden shrink-0 flex flex-col items-start ${
                    industry.highlight
                      ? "shadow-[0px_2px_16px_rgba(26,_38,_48,_0.12)]"
                      : "opacity-50"
                  }`

`self-stretch overflow-hidden flex items-center gap-[3rem] max-w-full text-left mq1050:flex-wrap mq750:gap-[1.5rem] ${
                index % 2 === 1 ? "mq1050:flex-wrap-reverse" : ""
              }`

`self-stretch overflow-hidden transition-all duration-300 ${
          isOpen ? "max-h-[500px] opacity-100 mt-[1rem]" : "max-h-0 opacity-0"
        }`

`self-stretch rounded-[16px] border overflow-hidden flex flex-col items-start p-[1.75rem] gap-[1rem] transition-all duration-300 ${
        isOpen
          ? "bg-color-white shadow-[0px_4px_16px_rgba(26,38,48,0.08)]"
          : "bg-color-white border-[#e2e5e9] border-solid"
      }`

`flex-1 relative leading-[2.125rem] font-abel ${
            isOpen ? "text-[#1a2530]" : "text-[#1a2530]"
          }`

`self-stretch overflow-hidden transition-all duration-300 ${
          isOpen ? "max-h-[1000px] opacity-100" : "max-h-0 opacity-0"
        }`

`cursor-pointer self-stretch rounded-[126px] flex items-center gap-[0.75rem] py-[1.25rem] px-[1.5rem] transition-all duration-200 ${
        isActive
          ? "bg-[#0461c3] text-color-white"
          : "bg-[#f7fafd] border border-[#e2e5e9] text-[#1a2530]"
      }`

`m-0 self-stretch relative text-[1.25rem] leading-[1.625rem] font-bold font-abel text-left ${
            isActive ? "text-color-white" : "text-[#1a2530]"
          }`

`w-full rounded-[28px] overflow-hidden flex flex-col items-center text-center text-[1rem] text-[#0bc111] font-['Proxima_Nova'] border-[4px] border-solid cursor-pointer transition-all duration-300 ease-in-out motion-reduce:transition-none focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0bc111] focus-visible:ring-offset-2 focus-visible:ring-offset-[#12171c] mq450:min-w-full mq450:flex-none ${
          isActive
            ? "bg-[rgba(242,240,251,0.08)] border-color-white"
            : "bg-[rgba(242,240,251,0.08)] border-[#1b2128]"
        } ${className}`

`self-stretch w-full relative max-w-full overflow-hidden shrink-0 object-cover transition-all duration-300 ease-in-out motion-reduce:transition-none mq450:h-[10rem] ${
            isActive ? "h-[10rem]" : "h-[5rem]"
          }`

`self-stretch rounded-t-[28px] rounded-b-none flex flex-col items-center py-[1.25rem] px-[1.5rem] gap-[0.75rem] mt-[-1.25rem] relative mq450:mt-0 transition-colors duration-300 ease-in-out motion-reduce:transition-none ${
            isActive ? "bg-color-white" : "bg-[#12171c]"
          }`

`rounded-[40px] flex items-center py-[0.25rem] px-[0.625rem] gap-[0.25rem] transition-colors duration-300 ease-in-out motion-reduce:transition-none ${
              isActive
                ? "bg-[rgba(11,193,17,0.12)]"
                : "bg-[rgba(11,193,17,0.2)]"
            }`

`m-0 self-stretch relative text-[1.25rem] leading-[1.75rem] font-bold font-[inherit] transition-colors duration-300 ease-in-out motion-reduce:transition-none ${
              isActive ? "text-[#161c2d]" : "text-[rgba(238,238,238,0.8)]"
            }`

`cursor-pointer w-[2.75rem] h-[2.75rem] rounded-[10px] border-solid border-[1px] flex items-center justify-center text-[1rem] transition-colors ${
                    page === number
                      ? "bg-[#1a8cd5] border-[#1a8cd5] text-color-white"
                      : "bg-color-white border-[#e2e5e9] text-[#1a2530] hover:bg-[#f7fafd]"
                  }`

`self-stretch overflow-hidden transition-all duration-300 ${
                isFirstOpen ? "max-h-[500px] opacity-100" : "max-h-0 opacity-0"
              }`
